ALTER TABLE security_action ADD COLUMN IF NOT EXISTS action_type TINYINT NOT NULL DEFAULT 0 AFTER id_security_action,
  ADD COLUMN IF NOT EXISTS cost_allocation DOUBLE NULL AFTER to_factor,
  ADD COLUMN IF NOT EXISTS cost_allocation_source VARCHAR(255) NULL AFTER cost_allocation,
  ADD COLUMN IF NOT EXISTS tax_treatment_de TINYINT NULL AFTER cost_allocation_source,
  ADD COLUMN IF NOT EXISTS cost_allocation_de DOUBLE NULL AFTER tax_treatment_de;
ALTER TABLE security_action_application ADD COLUMN IF NOT EXISTS cost_allocation DOUBLE NULL AFTER id_transaction_buy;
ALTER TABLE `transaction` ADD COLUMN IF NOT EXISTS security_action_role TINYINT NULL AFTER id_security_action_app;
ALTER TABLE security_action ADD COLUMN IF NOT EXISTS provider_split_factor DOUBLE NULL AFTER cost_allocation_de,
  ADD COLUMN IF NOT EXISTS history_basis TINYINT NULL AFTER provider_split_factor,
  ADD COLUMN IF NOT EXISTS history_factor DOUBLE NULL AFTER history_basis,
  ADD COLUMN IF NOT EXISTS history_basis_origin TINYINT NULL AFTER history_factor,
  ADD COLUMN IF NOT EXISTS history_connector VARCHAR(35) NULL AFTER history_basis_origin,
  ADD COLUMN IF NOT EXISTS history_url_extend VARCHAR(254) NULL AFTER history_connector,
  ADD COLUMN IF NOT EXISTS history_basis_applied TINYINT(1) NOT NULL DEFAULT 0 AFTER history_url_extend;
UPDATE security_action SET history_basis = 0 WHERE action_type = 1 AND history_basis IS NULL;

ALTER TABLE stockexchange ADD COLUMN IF NOT EXISTS regular_close TIME NULL AFTER time_close;

UPDATE stockexchange SET regular_close = '16:00:00'
WHERE mic IN ('XNYS', 'XNAS') AND time_zone = 'America/New_York' AND time_close > '16:00:00' AND regular_close IS NULL;

UPDATE stockexchange SET regular_close = '15:30:00'
WHERE mic = 'XTKS' AND time_zone = 'Asia/Tokyo' AND regular_close IS NULL;

-- Seed a missing global calendar year. Even one existing day preserves the administrator's calendar for that year.
SELECT candidates.trading_date
FROM (
  SELECT year_start, year_start + INTERVAL seq DAY AS trading_date
  FROM (SELECT DATE('2026-01-01') AS year_start UNION ALL SELECT DATE('2027-01-01')) AS years
  CROSS JOIN seq_0_to_364
) AS candidates
WHERE WEEKDAY(candidates.trading_date) < 5
  AND DATE_FORMAT(candidates.trading_date, '%m-%d') NOT IN ('01-01', '12-25')
  AND NOT EXISTS (
    SELECT 1 FROM trading_days_plus existing
    WHERE existing.trading_date >= candidates.year_start
      AND existing.trading_date < candidates.year_start + INTERVAL 1 YEAR
  );

CREATE TABLE IF NOT EXISTS `instrument_logo` (
  `id_instrument_logo` INT NOT NULL AUTO_INCREMENT,
  `isin`               VARCHAR(12) DEFAULT NULL,
  `name`               VARCHAR(120) NOT NULL,
  `logo_scope`         TINYINT NOT NULL DEFAULT 0 COMMENT '0=COMPANY, 1=ISSUER',
  `asset_path`         VARCHAR(160) DEFAULT NULL COMMENT 'Relativer Pfad unter assets/company-logos/ fuer Deployed-SVGs',
  `svg_content`        MEDIUMTEXT DEFAULT NULL COMMENT 'Bereinigtes SVG fuer DB-gespeicherte Logos',
  `content_sha256`     CHAR(64) NOT NULL,
  `name_patterns`      VARCHAR(500) DEFAULT NULL COMMENT 'Zeilengetrennte Ganzwort-Muster fuer automatisches Herausgeber-Matching',
  `hosts`              VARCHAR(500) DEFAULT NULL COMMENT 'Zeilengetrennte Produktlink-Hosts fuer automatisches Herausgeber-Matching',
  `host_suffixes`      VARCHAR(255) DEFAULT NULL COMMENT 'Zeilengetrennte Host-Suffixe (z.B. .vanguard.com)',
  `created_by`         INT NOT NULL,
  `creation_time`      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_modified_by`   INT NOT NULL,
  `last_modified_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `version`            INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id_instrument_logo`),
  UNIQUE KEY `uk_instrument_logo_isin` (`isin`),
  UNIQUE KEY `uk_instrument_logo_name` (`name`),
  UNIQUE KEY `uk_instrument_logo_asset_path` (`asset_path`),
  CONSTRAINT `chk_instrument_logo_source` CHECK (
    (`asset_path` IS NOT NULL AND `svg_content` IS NULL) OR
    (`asset_path` IS NULL AND `svg_content` IS NOT NULL)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `security`
  ADD COLUMN IF NOT EXISTS `id_instrument_logo` INT DEFAULT NULL AFTER `fund_tax_class`;

ALTER TABLE `security` DROP FOREIGN KEY IF EXISTS `FK_Security_InstrumentLogo`;
DROP INDEX IF EXISTS `idx_security_instrument_logo` ON `security`;
ALTER TABLE `security` ADD KEY `idx_security_instrument_logo` (`id_instrument_logo`);
ALTER TABLE `security`
  ADD CONSTRAINT `FK_Security_InstrumentLogo`
  FOREIGN KEY (`id_instrument_logo`) REFERENCES `instrument_logo` (`id_instrument_logo`)
  ON DELETE RESTRICT;

-- At most 100 uploaded logos per creator, and 20 creates per user and day.
   `created_by`, `last_modified_by`, `last_modified_time`, `version`)
SELECT 0, x.entity_name, x.relation_entity_name, x.count_scope, x.owner_scope, x.default_value,
  0, 0, CURRENT_TIMESTAMP, 0
FROM (SELECT 'InstrumentLogo' AS entity_name, CAST(NULL AS CHAR(40)) AS relation_entity_name,
  CAST(NULL AS SIGNED) AS count_scope, 2 AS owner_scope,
  CAST(NULL AS CHAR) AS property_name, 100 AS default_value) x;

   `created_by`, `last_modified_by`, `last_modified_time`, `version`)
SELECT 1, 'InstrumentLogo', NULL, NULL, NULL, 20, 0, 0, CURRENT_TIMESTAMP, 0;

